insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('1', NULL, '1', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Below a crore, growth still comes from knowing exactly who buys; a vague target customer is the most common reason revenue plateaus here.', '2', NULL, '25L_1Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('2', NULL, '3', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'The founder can still be the seller at this size, but the process has to exist outside their head or it cannot be repeated on a bad month.', '2', NULL, '25L_1Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('3', NULL, '27', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Revenue at this band is still fragile; build decisions have to cite evidence from real customers rather than the founder''s conviction.', '2', NULL, '25L_1Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('4', NULL, '22', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'You cannot manage toward a crore on numbers you cannot see on a schedule.', '2', NULL, '25L_1Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('5', NULL, '23', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Knowing what one unit of business earns and costs is what separates growing revenue from growing losses.', '2', NULL, '25L_1Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('6', NULL, '31', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'contextual', 'Being able to say why you are the right choice becomes load-bearing once you are selling to strangers rather than your network.', '2', NULL, '25L_1Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('7', NULL, '1', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Segment clarity is what lets acquisition be delegated; without it, only the founder knows who to chase.', '2', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('8', NULL, '2', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'At this band referrals and founder network stop being enough; at least one channel has to work on purpose.', '2', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('9', NULL, '3', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'A documented sales process is the precondition for anyone other than the founder ever closing.', '2', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('10', NULL, '4', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Forecasting becomes necessary once the business is committing to spend against expected revenue.', '2', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('11', NULL, '8', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Decisions need owners other than the founder, or the founder becomes the ceiling on throughput.', '2', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('12', NULL, '17', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Core work has to happen the same way twice before more people can be added to it.', '2', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('13', NULL, '22', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Monthly numbers on a schedule, trusted enough to decide on.', '2', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('14', NULL, '23', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Margin by product or segment is what tells you which part of the growth to fund.', '2', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('15', NULL, '24', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Growth consumes cash; runway has to be forecast rather than discovered.', '2', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('16', NULL, '34', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'contextual', 'Stated goals for a period, and knowing whether you are hitting them.', '2', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('17', NULL, '3', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'The sales process has to be owned and improved by someone whose job it is, not maintained by the founder between other things.', '3', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('18', NULL, '5', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Someone other than the founder has to be able to win business. This is the single capability that most often blocks this band.', '3', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('19', NULL, '4', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Pipeline has to be visible to the person accountable for it, not only to the founder.', '3', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('20', NULL, '2', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Acquisition has to run as a system with a named owner and a budget.', '3', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('21', NULL, '6', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'At this size, churn quietly cancels out new sales unless it is measured and managed.', '2', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('22', NULL, '8', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Routine decisions must not reach the founder at all.', '3', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('23', NULL, '9', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'The business has to keep running when the founder is away, or every holiday is a risk event.', '3', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('24', NULL, '7', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'The founder''s week has to have a deliberate shape, or it fills with whatever is loudest.', '2', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('25', NULL, '12', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Written scopes and unambiguous ownership -- the prerequisite for holding anyone accountable.', '2', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('26', NULL, '13', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Hiring becomes a repeated act at this band; doing it by instinct each time is how a team gets expensive and uneven.', '2', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('27', NULL, '14', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Performance has to be discussed on a schedule rather than when something goes wrong.', '2', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('28', NULL, '15', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'A rhythm for deciding and informing, so information does not route through the founder.', '2', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('29', NULL, '17', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Processes need an owner who improves them, not just a founder who remembers them.', '3', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('30', NULL, '18', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'How-to knowledge outside individual heads, or every departure is a crisis.', '2', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('31', NULL, '20', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Operational health visible without asking someone.', '2', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('32', NULL, '22', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Reporting owned by someone competent, on a cycle, and used for decisions.', '3', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('33', NULL, '24', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Cash position known at any time, with a tight scenario already thought through.', '2', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('34', NULL, '25', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'A budget that spending is reviewed against.', '2', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('35', NULL, '31', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Positioning consistent across channels, because the founder is no longer in every conversation.', '2', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('36', NULL, '34', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Goals for a period, with risks identified and owned.', '2', NULL, '5Cr_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('37', NULL, '9', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Nothing critical may depend on the founder personally.', '3', NULL, 'above_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('38', NULL, '11', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'The founder leads through others; doing the work themselves is now the failure mode.', '3', NULL, 'above_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('39', NULL, '12', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Ownership of each outcome is unambiguous and revisited as the business changes.', '3', NULL, 'above_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('40', NULL, '15', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'The operating rhythm has to survive busy periods without the founder enforcing it.', '3', NULL, 'above_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('41', NULL, '16', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'At this size retention costs are real and culture stops being implicit.', '2', NULL, 'above_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('42', NULL, '19', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Defects have to be caught before the customer finds them, systematically.', '2', NULL, 'above_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('43', NULL, '20', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Monitoring that drives action, owned by someone.', '3', NULL, 'above_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('44', NULL, '28', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'What is promised ships when it was said to, without heroics.', '2', NULL, 'above_25Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('45', 'B2B', '4', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'B2B cycles are long enough that pipeline has to be owned and forecast, not reviewed occasionally.', '3', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('46', 'B2C', '2', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'A B2C business at this band lives or dies on repeatable paid or organic acquisition, so it needs an owner rather than a process.', '3', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('47', 'B2C', '6', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Repeat purchase is the economics of B2C; without measurement, acquisition spend is unbounded.', '2', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('48', NULL, '6', '2026-09-19 13:41:00.304024+00', NULL, 'saas', 'core', 'Retention IS the business model in SaaS; it has to be owned and improved, not merely measured.', '3', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('49', 'B2C', '6', '2026-09-19 13:41:00.304024+00', NULL, 'saas', 'core', 'A B2C SaaS business is hit by both rules above -- retention is the model AND consumer churn is higher -- so the combined case is stated explicitly rather than left for the resolver to guess between them.', '3', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('50', NULL, '23', '2026-09-19 13:41:00.304024+00', NULL, 'ecommerce_d2c', 'core', 'In D2C, contribution margin per order decides whether growth is progress; it needs a dedicated owner.', '3', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('51', NULL, '22', '2026-09-19 13:41:00.304024+00', NULL, 'fintech', 'core', 'Fintech reporting is subject to external scrutiny from early on, so visibility has to be owned rather than adequate.', '3', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('52', NULL, '9', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Six months is not long enough to build founder independence from scratch; it has to be close to true already.', '3', NULL, '5Cr_25Cr', '6_months', '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('53', NULL, '18', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'With this little time, documentation has to be current and owned rather than something to start.', '3', NULL, '5Cr_25Cr', '6_months', '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('54', NULL, '5', '2026-09-19 13:41:00.304024+00', NULL, NULL, 'core', 'Twelve months means hiring and ramping a seller now; the capability cannot wait for revenue to justify it.', '3', NULL, '5Cr_25Cr', '12_months', '2026-09-19 13:41:00.304024+00') on conflict do nothing;
insert into "capability_requirements" ("requirement_id", "business_model", "capability_id", "created_at", "from_stage_order", "industry_code", "necessity", "rationale", "required_level", "source_document", "target_revenue_band", "target_time_horizon", "updated_at") values ('55', NULL, '27', '2026-09-19 13:41:00.304024+00', '2', NULL, 'core', 'A founder still at or past Validation reaching for 1-5Cr has not yet proven the thing they intend to scale; discovery stays load-bearing.', '2', NULL, '1Cr_5Cr', NULL, '2026-09-19 13:41:00.304024+00') on conflict do nothing;
